// r10uvm11 t4 — a `this.`-ROOTED receiver.  UVM's TLM port/export classes are
// generated by `UVM_GET_IMP(this.m_if, T, t)` and friends, so every one of
// their ~40 forwarding methods calls `this.m_if.can_get()`.  The first cut of
// deepRecvCall11 flattened `this` into a path segment and built a 3-element
// hier_path; golden emits NO hier_path there at all (measured on SeqDriver:
// zero golden elements for uvm_get_export::can_get).  What does it build?
package p4;

  class Leaf;
    function void doit(); endfunction
  endclass

  class Inner;
    int v;
    Leaf inner;
    function int get(); return v; endfunction
    function void doit(); v = 1; endfunction
    function void set(int a); v = a; endfunction
  endclass

  class Caller;
    Inner m_if;
    Inner arr[4];

    // expression position
    function int e_this();
      return this.m_if.get();
    endfunction

    // expression position, no `this`
    function int e_plain();
      return m_if.get();
    endfunction

    // expression position, this + index
    function int e_this_idx();
      return this.arr[1].get();
    endfunction

    // statement position
    function void s_this();
      this.m_if.doit();
    endfunction

    function void s_this_idx();
      this.arr[2].doit();
    endfunction

    // `this` alone as the receiver
    function void s_this_only();
      this.doit2();
    endfunction

    function void doit2(); endfunction

    // `this` alone as the receiver, EXPRESSION position
    function int e_this_only();
      return this.get2();
    endfunction

    function int get2(); return 7; endfunction

    // this-rooted with ARGUMENTS on the final method
    function void s_this_args();
      this.m_if.set(5);
    endfunction

    // four names
    function void s_this_deep();
      this.m_if.inner.doit();
    endfunction
  endclass

endpackage

module top4;
  p4::Caller c;
  initial begin
    c = new();
    c.s_this();
  end
endmodule
